kind=sys.argv[1];out=base/kind;out.mkdir(exist_ok=False);rows=[]
def run(name,command,timeout=300,env=None):
 start=time.time();command=list(map(str,command))
 with (out/(name+'.log')).open('x') as log:
  try:code=subprocess.run(command,cwd=out,env=env,stdout=log,stderr=subprocess.STDOUT,timeout=timeout).returncode
  except subprocess.TimeoutExpired:code=124
 rows.append(dict(name=name,command=command,exit_code=code,started=start,finished=time.time(),cwd=str(out),device_visibility=os.environ.get('ASCEND_RT_VISIBLE_DEVICES')))
 write_json(out/'processes.json',rows);print(name,code,flush=True);return code
