 for target in ('device-services','weighted-projection','block-kv-messages','device-optimizer','weighted-head','weighted-kv-update','weighted-aggregate','weighted-region','weighted-residual','weighted-kv-query','weighted-kv-full','block-read-selection','block-kv-sequence','block-settle-flow','block-settle-session','block-settle-model'):
